import{_ as t,o as r,c as a,a5 as i}from"./chunks/framework.CslsFoWx.js";const m=JSON.parse('{"title":"Protocole de validation sur matériel réel (spec 11)","description":"","frontmatter":{},"headers":[],"relativePath":"tests/validation-materiel.md","filePath":"generated/tests/validation-materiel.md","lastUpdated":null}'),s={name:"tests/validation-materiel.md"};function o(n,e,l,u,d,c){return r(),a("div",null,[...e[0]||(e[0]=[i('<div><h1 id="protocole-de-validation-sur-materiel-reel-spec-11" tabindex="-1">Protocole de validation sur matériel réel (spec 11) <a class="header-anchor" href="#protocole-de-validation-sur-materiel-reel-spec-11" aria-label="Permalink to &quot;Protocole de validation sur matériel réel (spec 11)&quot;">​</a></h1><blockquote><p>Objectif : valider sur de <strong>vrais appareils</strong> ce que les tests automatiques et les émulateurs ne peuvent pas prouver. Chaque essai se fait avec l&#39;écran <strong>« Diagnostic matériel »</strong> des caisses (menu ⋮ / ⋯) : il mesure, affiche le verdict et produit un <strong>rapport copiable</strong> à coller dans le tableau de résultats en bas de ce document. Durée estimée : 30 à 45 min par caisse.</p></blockquote><h2 id="materiel-a-reunir" tabindex="-1">Matériel à réunir <a class="header-anchor" href="#materiel-a-reunir" aria-label="Permalink to &quot;Matériel à réunir&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Élément</th><th>Exemple</th><th>Pour quoi</th></tr></thead><tbody><tr><td>Terminal Android (≥ Android 8)</td><td>tablette ou terminal POS</td><td>app Android</td></tr><tr><td>iPad ou iPhone (iOS 17+)</td><td>—</td><td>app iOS (installation via Xcode, signature d&#39;équipe)</td></tr><tr><td>Douchette <strong>Bluetooth</strong> en mode clavier (HID)</td><td>Zebra, Honeywell, Netum…</td><td>RG-HW-09</td></tr><tr><td>Douchette <strong>USB</strong> (Android)</td><td>idem</td><td>RG-HW-09</td></tr><tr><td>Imprimante thermique <strong>réseau</strong> ESC/POS 80 mm (et 58 mm si possible)</td><td>Epson TM-T20, Xprinter…</td><td>RG-HW-02/03/06</td></tr><tr><td>Tiroir-caisse <strong>RJ11</strong> branché sur l&#39;imprimante</td><td>—</td><td>RG-HW-08, RG-CASH-17</td></tr><tr><td>Planche d&#39;étiquettes A4 imprimée depuis le back-office (Étiquettes)</td><td>gabarit 24</td><td>CA-10</td></tr><tr><td>Produits à code-barres réels (EAN-13, EAN-8, UPC-A)</td><td>eau, café…</td><td>RG-HW-10</td></tr></tbody></table><p>Prérequis : serveur joignable, caisse appairée, un manager avec PIN (Équipe), une imprimante configurée (Réglages imprimante : IP, port 9100, largeur).</p><h2 id="_1-douchette-hid-bluetooth-puis-usb-—-rg-hw-09" tabindex="-1">1. Douchette HID (Bluetooth, puis USB) — RG-HW-09 <a class="header-anchor" href="#_1-douchette-hid-bluetooth-puis-usb-—-rg-hw-09" aria-label="Permalink to &quot;1. Douchette HID (Bluetooth, puis USB) — RG-HW-09&quot;">​</a></h2><p>Configuration de la douchette : mode clavier, <strong>suffixe Entrée</strong>, pas de préfixe, clavier <strong>français</strong> si proposé (sinon US : vérifier les chiffres).</p><ol><li>Diagnostic matériel → <strong>Douchette</strong> → scanner 5 codes différents (dont un code <strong>interne</strong> <code>20…</code> d&#39;une étiquette A4). <ul><li>Attendu : pour chaque code, « Reconnu comme scan douchette ✓ », durée de saisie <strong>&lt; 100 ms</strong>, clé EAN « valide ».</li></ul></li><li>Écran de vente, <strong>champ de recherche actif</strong> (clavier virtuel ouvert) → scanner un produit. <ul><li>Attendu : le produit est ajouté au panier, le code <strong>n&#39;apparaît pas</strong> dans la recherche.</li></ul></li><li>Scanner pendant qu&#39;une <strong>boîte de dialogue</strong> est ouverte (ex. Rapport X). <ul><li>Attendu à constater : comportement actuel connu = scan perdu sur Android (dette tracée) — noter ce qui se passe.</li></ul></li><li>Mettre la douchette en veille puis la réveiller ; scanner. <ul><li>Attendu : reconnexion Bluetooth automatique, premier scan pris en compte.</li></ul></li></ol><h2 id="_2-scan-camera-—-rg-hw-10" tabindex="-1">2. Scan caméra — RG-HW-10 <a class="header-anchor" href="#_2-scan-camera-—-rg-hw-10" aria-label="Permalink to &quot;2. Scan caméra — RG-HW-10&quot;">​</a></h2><ol><li>Diagnostic matériel → <strong>Caméra</strong> → viser un EAN-13 net, bon éclairage. <ul><li>Attendu : détection en <strong>&lt; 500 ms</strong>, bip + vibration.</li></ul></li><li>Répéter avec : EAN-8, UPC-A, un <strong>QR</strong>, un <strong>Code 128</strong>, un code d&#39;étiquette A4 interne, éclairage faible (torche). <ul><li>Attendu : tous détectés ; noter les durées.</li></ul></li></ol><h2 id="_3-imprimante-thermique-reseau-—-rg-hw-02-03-04-05-06" tabindex="-1">3. Imprimante thermique réseau — RG-HW-02/03/04/05/06 <a class="header-anchor" href="#_3-imprimante-thermique-reseau-—-rg-hw-02-03-04-05-06" aria-label="Permalink to &quot;3. Imprimante thermique réseau — RG-HW-02/03/04/05/06&quot;">​</a></h2><ol><li>Diagnostic matériel → <strong>Imprimante</strong> → « Ticket de test ». <ul><li>Attendu : ticket complet, accents corrects ou remplacés proprement, coupe partielle, durée affichée.</li></ul></li><li>Encaisser une vente réelle → ticket : n° fiscal + empreinte (spec 15), TVA, paiements, rendu.</li><li><strong>Débrancher le câble réseau</strong> de l&#39;imprimante, encaisser 2 ventes, rebrancher. <ul><li>Attendu : ventes jamais bloquées (RG-HW-05), tickets imprimés <strong>en entier</strong> au retour, dans l&#39;ordre.</li></ul></li><li>Ouvrir le capot / retirer le papier pendant une impression. <ul><li>Attendu à constater : statuts <code>COVER_OPEN</code> / <code>PAPER_OUT</code> (RG-HW-06) <strong>non implémentés à ce jour</strong> — noter le comportement.</li></ul></li><li>Si une imprimante <strong>58 mm</strong> est disponible : changer la largeur dans les réglages, réimprimer. <ul><li>Attendu : rien ne déborde (32 colonnes).</li></ul></li><li>Clôture de session → <strong>rapport Z</strong> imprimé ; réimpression → mention <strong>DUPLICATA</strong> (sous PIN manager).</li></ol><h2 id="_4-tiroir-caisse-—-rg-hw-08-rg-cash-17" tabindex="-1">4. Tiroir-caisse — RG-HW-08, RG-CASH-17 <a class="header-anchor" href="#_4-tiroir-caisse-—-rg-hw-08-rg-cash-17" aria-label="Permalink to &quot;4. Tiroir-caisse — RG-HW-08, RG-CASH-17&quot;">​</a></h2><ol><li>Diagnostic matériel → <strong>Tiroir</strong> → PIN manager + motif. <ul><li>Attendu : le tiroir s&#39;ouvre ; message « Tiroir ouvert (approuvé par … ») ; trace visible au back-office (PIN &amp; approbations).</li></ul></li><li>Imprimante <strong>éteinte</strong> → même essai. <ul><li>Attendu : « Tiroir non ouvert : imprimante injoignable », <strong>rien</strong> ne s&#39;ouvre au rallumage (pas de file).</li></ul></li></ol><h2 id="_5-son-et-vibration" tabindex="-1">5. Son et vibration <a class="header-anchor" href="#_5-son-et-vibration" aria-label="Permalink to &quot;5. Son et vibration&quot;">​</a></h2><ol><li>Diagnostic matériel → <strong>Bip</strong> : son audible, vibration (Android).</li></ol><h2 id="_6-reseau-hors-ligne" tabindex="-1">6. Réseau, hors ligne <a class="header-anchor" href="#_6-reseau-hors-ligne" aria-label="Permalink to &quot;6. Réseau, hors ligne&quot;">​</a></h2><ol><li>Diagnostic matériel → <strong>Réseau</strong> : serveur joignable, latence.</li><li><strong>Couper le Wi-Fi</strong>, encaisser 3 ventes, imprimer, clôturer une session ; rétablir. <ul><li>Attendu : tout fonctionne hors ligne ; au retour, synchro complète (intégrité fiscale « OK » au back-office).</li></ul></li></ol><h2 id="_7-hub-local-mdns-nsd-bonjour-—-spec-10-§4-4-§8" tabindex="-1">7. Hub local (mDNS / NSD / Bonjour) — spec 10 §4.4 / §8 <a class="header-anchor" href="#_7-hub-local-mdns-nsd-bonjour-—-spec-10-§4-4-§8" aria-label="Permalink to &quot;7. Hub local (mDNS / NSD / Bonjour) — spec 10 §4.4 / §8&quot;">​</a></h2><p>Le hub est dans les apps depuis le lot 2.6 (élection, relais TCP, rattrapage) et sécurisé aux lots 2.26 / 2.28 (clé LAN du magasin, identité Ed25519 par appareil). Prouvé entre émulateur et simulateur, <strong>à rejouer sur 3 appareils physiques</strong> (2 Android + 1 iPhone) sur le Wi-Fi du magasin, internet coupé :</p><ul><li>[ ] Permissions : iOS demande « réseau local » au premier parcours ; Android découvre les pairs (NSD) — attention à l&#39;isolation AP / IGMP des box : les trois appareils doivent se voir dans « Diagnostic matériel › Hub ».</li><li>[ ] Élection : la caisse marquée principale est hub partout ; statut « temps réel magasin » sur les trois.</li><li>[ ] Relais &lt; 2 s : un envoi en cuisine depuis le téléphone apparaît sur le KDS / la caisse sans internet.</li><li>[ ] Chute brutale du hub (kill de l&#39;app, Wi-Fi coupé) : ré-élection ≤ 20 s, rattrapage des événements manqués au retour.</li><li>[ ] iPhone hub mis en arrière-plan : ré-élection ailleurs en quelques secondes ; retour au premier plan → il rejoint.</li><li>[ ] Sécurité LAN : un appareil <strong>révoqué</strong> au back-office est refusé sur le LAN à son prochain Hello (sans serveur) ; un appareil appairé sur un <strong>autre magasin</strong> ne rejoint pas ; après <strong>rotation de la clé LAN</strong>, les appareils reprennent au pull suivant. Le diagnostic montre le compteur de refus (<code>rejected</code>).</li><li>[ ] Identité Ed25519 : chaque appareil a sa clé publique au back-office (<code>GET /pos/lan-peers</code>) ; un appareil dont la clé a été remplacée (ré-appairage) est refusé jusqu&#39;à sa nouvelle synchronisation.</li></ul><h2 id="_8-sauvegarde-restauration-—-bases-exclues-rg-auth-22-spec-10-§4-5" tabindex="-1">8. Sauvegarde / restauration — bases exclues (RG-AUTH-22, spec 10 §4.5) <a class="header-anchor" href="#_8-sauvegarde-restauration-—-bases-exclues-rg-auth-22-spec-10-§4-5" aria-label="Permalink to &quot;8. Sauvegarde / restauration — bases exclues (RG-AUTH-22, spec 10 §4.5)&quot;">​</a></h2><p>Déjà <strong>prouvé en environnement de développement</strong> (lot 2.27, <a href="/VendoraSystem-docs/preuves/2026-10-30-dette-technique">captures</a>) : émulateur Android → <code>bmgr backupnow pos.android</code> = « Backup is not allowed », <code>adb backup</code> = archive vide ; simulateur iPhone → attribut <code>com_apple_backup_excludeItem</code> présent sur le dossier <code>databases</code> et chaque fichier. À refaire une fois sur de vrais appareils :</p><ul><li>[ ] <strong>Android</strong> : compte Google de test, <em>Paramètres › Sauvegarde</em> → « Sauvegarder maintenant » ; sur un second appareil, restaurer depuis cette sauvegarde à la configuration → l&#39;app POS est réinstallée <strong>vide</strong> (écran d&#39;appairage, aucune vente, aucun PIN). Variante : <em>Transfert d&#39;appareil à appareil</em> (câble / Wi-Fi) → idem.</li><li>[ ] <strong>iOS</strong> : sauvegarde iCloud (ou Finder) de l&#39;iPhone caisse ; restaurer sur un second iPhone → l&#39;app POS est <strong>vide</strong> (pas de <code>pos.db</code>, Keychain <code>ThisDeviceOnly</code> non restauré) → ré-appairage, resynchronisation depuis le serveur.</li><li>[ ] Après restauration : vérifier au back-office que l&#39;ancien appareil est toujours appairé (le révoquer si remplacé).</li></ul><h2 id="resultats" tabindex="-1">Résultats <a class="header-anchor" href="#resultats" aria-label="Permalink to &quot;Résultats&quot;">​</a></h2><p>Coller ici le rapport de l&#39;écran Diagnostic matériel de chaque caisse, puis compléter :</p><table tabindex="0"><thead><tr><th>Date</th><th>Caisse (modèle, OS)</th><th>Essai</th><th>Résultat</th><th>Remarque</th></tr></thead><tbody><tr><td></td><td></td><td></td><td></td><td></td></tr></tbody></table></div>',1)])])}const h=t(s,[["render",o]]);export{m as __pageData,h as default};
